import pysnooper.utils as utils


def test_get_shortish_repr_strips_carriage_returns_and_newlines():
    class Item:
        pass

    def custom_repr(item):
        return "first\r\nsecond\nthird\rfourth"

    result = utils.get_shortish_repr(
        Item(),
        custom_repr=((Item, custom_repr),),
    )

    assert result == "firstsecondthirdfourth"


def test_get_shortish_repr_returns_fallback_when_repr_raises():
    class Item:
        pass

    def failing_repr(item):
        raise RuntimeError("repr failed")

    result = utils.get_shortish_repr(
        Item(),
        custom_repr=((Item, failing_repr),),
    )

    assert result == "REPR FAILED"


def test_get_shortish_repr_normalizes_and_truncates_repr():
    class Item:
        pass

    raw_repr = "<Item object at 0x1234567890>"

    def custom_repr(item):
        return raw_repr

    normalized = utils.normalize_repr(raw_repr)
    expected = utils.truncate(normalized, 10)

    result = utils.get_shortish_repr(
        Item(),
        custom_repr=((Item, custom_repr),),
        max_length=10,
        normalize=True,
    )

    assert result == expected
    assert "0x1234567890" not in result
    assert len(result) <= 10
